// A store header says one thing once (ZDD-9, from the ZDD-7 campaign's
// CR-196; decision 0047): the parser strips any pair of quotes and keeps a
// repeated key's last value, so `importance: "high'` read as `high` and a
// second `kind:` silently won. Lint now fails a blessing or semantic-map
// page whose header repeats a key, or whose value opens with a quote and
// does not close with the same one, naming the file and line. The parser's
// output is unchanged: no generated byte moves.
// Run: node --test "test/*.test.mjs"
import { test } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { writeFileSync, rmSync, mkdtempSync, cpSync, mkdirSync } from "node:fs";
import { dirname, resolve, join } from "node:path";
import { tmpdir } from "node:os";
import { fileURLToPath } from "node:url";
import { headerProblems, parseFrontmatter } from "../src/core/lib/frontmatter.mjs";

const PKG = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const BIN = join(PKG, "bin", "zdd-engine.mjs");
const FIXTURE = join(PKG, "test", "fixture");

test("headerProblems: a repeated key and a value whose quotes do not match, by line; an apostrophe inside a value, matched quotes and CRLF are fine", () => {
  const text = ["---", "where: src/a.ts", "kind: copy", "importance: \"high'", "kind: extend", "title: Bob's page", 'note: "quoted"', "other: 'single'", "open: \"no end", "close: no start'", "tags: [a, b]", "---", "", "Body: with: colons", ""].join("\r\n");
  assert.deepEqual(headerProblems(text), [
    { line: 4, key: "importance", problem: "quotes" },
    { line: 5, key: "kind", problem: "repeated", first: 3 },
    { line: 9, key: "open", problem: "quotes" },
  ]);
  assert.deepEqual(headerProblems("---\nkind: copy\n---\n"), []);
  assert.deepEqual(headerProblems("no header at all\n"), []);
  // The parser's own reading is unchanged.
  assert.equal(parseFrontmatter(text).frontmatter.kind, "extend");
  assert.equal(parseFrontmatter(text).frontmatter.importance, "high");
});

test("lint: a blessing or a map page with a repeated key or mismatched quotes fails, naming the file and line; a clean store passes", (t) => {
  const repo = mkdtempSync(join(tmpdir(), "zdd-header-"));
  t.after(() => rmSync(repo, { recursive: true, force: true }));
  cpSync(FIXTURE, repo, { recursive: true });
  const lint = () => spawnSync(process.execPath, [BIN, "lint"], { cwd: repo, encoding: "utf8" });
  assert.equal(spawnSync(process.execPath, [BIN, "derive"], { cwd: repo, encoding: "utf8" }).status, 0);
  const clean = lint();
  assert.equal(clean.status, 0, clean.stderr);
  writeFileSync(join(repo, "zdd", "blessings", "doubled.md"), "---\nwhere: src/app/page.tsx\nkind: extend\nkind: copy\nimportance: \"high'\n---\n\nAdding a doubled thing? Copy the page, because it is thin.\n");
  mkdirSync(join(repo, "zdd", "map", "apps"), { recursive: true });
  writeFileSync(join(repo, "zdd", "map", "apps", "twice.md"), "---\ntype: Application\ntitle: 'Twice\ntype: Feature\n---\n\nAn app.\n");
  const r = lint();
  assert.equal(r.status, 1);
  assert.match(r.stderr, /zdd\/blessings\/doubled\.md:4: 'kind' is written twice \(first on line 3\) — ZDD reads only the last one; keep one line/, r.stderr);
  assert.match(r.stderr, /zdd\/blessings\/doubled\.md:5: 'importance' opens with one quote and does not close with the same one — ZDD would read it as 'high'; close it with the same quote, or drop both/, r.stderr);
  assert.match(r.stderr, /zdd\/map\/apps\/twice\.md:3: 'title' opens with one quote and does not close with the same one/, r.stderr);
  assert.match(r.stderr, /zdd\/map\/apps\/twice\.md:4: 'type' is written twice \(first on line 2\)/, r.stderr);
});
